import type { UiContractSigningStatus } from '~/client';
import type { BadgeVariants } from '~/components/ui/badge';

interface UiContractSigningStatusEntry {
  label: string;
  variant: BadgeVariants;
}

export const uiContractSigningStatusConfig: Record<UiContractSigningStatus, UiContractSigningStatusEntry> = {
  not_sent: { label: 'Not Sent', variant: 'default' },
  pending: { label: 'Pending', variant: 'info' },
  signed: { label: 'Signed', variant: 'success' },
};

const defaultStatus: UiContractSigningStatusEntry = { label: '', variant: 'default' };

export function getUiContractSigningStatus(status: UiContractSigningStatus): UiContractSigningStatusEntry {
  return uiContractSigningStatusConfig[status] ?? { ...defaultStatus, label: snakeCaseToCapitalizedCase(status) };
}
