<template>
  <div
    class="inline-flex w-fit items-center rounded-md bg-warning-foreground/10 px-2.5 py-1 text-xs font-medium text-warning-foreground tabular-nums"
  >
    <ClockIcon class="size-3.5 shrink-0" />
    <span class="ml-1.5 text-[10px] font-semibold uppercase tracking-wide opacity-70">{{ label }}</span>
    <span class="ml-1.5">{{ formatted }}</span>
  </div>
</template>

<script setup lang="ts">
import { computed } from 'vue';
import { ClockIcon } from 'lucide-vue-next';
import { formatDateTzToFormat } from '~/utils/formatDateToFormat';

interface Props {
  expiresAt: string;
  expired?: boolean;
}

const props = withDefaults(defineProps<Props>(), { expired: false });

const { timezone } = useUserRole();

const label = computed(() => (props.expired ? 'Expired' : 'Exp'));
const formatted = computed(() =>
  formatDateTzToFormat(new Date(props.expiresAt), 'MMM d, yyyy, h:mm a', timezone.value)
);
</script>
